using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Mvc.ModelBinding.Validation;

namespace EmployeeManagement.API.Models;

public class Employee
{
    public int EmployeeId { get; set; }

    // Generated by the API
    [ValidateNever]
    public string EmployeeCode { get; set; } = string.Empty;

    [Required(ErrorMessage = "First name is required.")]
    [RegularExpression(@"^[A-Za-zÀ-ÿñÑ .'-]+$", ErrorMessage = "First name can only contain letters.")]
    public string FirstName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Last name is required.")]
    [RegularExpression(@"^[A-Za-zÀ-ÿñÑ .'-]+$", ErrorMessage = "Last name can only contain letters.")]
    public string LastName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Enter a valid email address.")]
    public string Email { get; set; } = string.Empty;

    [RegularExpression(@"^(09|\+639)\d{9}$", ErrorMessage = "Phone must use 09XXXXXXXXX or +639XXXXXXXXX.")]
    public string? Phone { get; set; }

    public string? Position { get; set; }

    public DateTime HireDate { get; set; }

    [Required(ErrorMessage = "Status is required.")]
    public string Status { get; set; } = "Active";

    [Range(1, int.MaxValue, ErrorMessage = "Please select a department.")]
    public int DepartmentId { get; set; }

    // Set only by the photo upload endpoint, e.g. "/uploads/employees/abc.jpg"
    [ValidateNever]
    public string? ProfileImageUrl { get; set; }

    [ValidateNever]
    public Department? Department { get; set; }
}
